[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $FixtureRoot,
    [Parameter(Mandatory)] [string] $OutputDirectory,
    [string] $OracleContractPath = (Join-Path $PSScriptRoot 'g0.5-lossy-audio-oracle-contract.json'),
