Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Hash([string] $Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Existing([string] $Path, [string] $Label) { if (-not [IO.Path]::IsPathRooted($Path) -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "$Label must be an existing absolute file." }; [IO.Path]::GetFullPath($Path) }
function ExistingDirectory([string] $Path, [string] $Label) { if (-not [IO.Path]::IsPathRooted($Path) -or -not (Test-Path -LiteralPath $Path -PathType Container)) { throw "$Label must be an existing absolute directory." }; [IO.Path]::GetFullPath($Path) }
function NewDirectory([string] $Path) { if (-not [IO.Path]::IsPathRooted($Path) -or (Test-Path -LiteralPath $Path)) { throw 'OutputDirectory must be an absolute new directory.' }; [IO.Directory]::CreateDirectory($Path).FullName }

$FixtureRoot = ExistingDirectory $FixtureRoot 'FixtureRoot'; $OutputDirectory = NewDirectory $OutputDirectory
$OracleContractPath = Existing $OracleContractPath 'OracleContractPath'; $AmendmentPath = Existing $AmendmentPath 'AmendmentPath'; $WorkloadContractPath = Existing $WorkloadContractPath 'WorkloadContractPath'; $V4RetentionManifestPath = Existing $V4RetentionManifestPath 'V4RetentionManifestPath'; $V4AuthoritativeControlReportPath = Existing $V4AuthoritativeControlReportPath 'V4AuthoritativeControlReportPath'
if ((Hash $OracleContractPath) -ne '119A4C179BFA010F3202DBF6AA368E42EDE5FD0FC23EF2781AA9C7F63540CBE4') { throw 'V5 must bind the exact frozen V3 contract.' }
$oracle = Get-Content -LiteralPath $OracleContractPath -Raw | ConvertFrom-Json -Depth 64; $amendment = Get-Content -LiteralPath $AmendmentPath -Raw | ConvertFrom-Json -Depth 64; $workloads = Get-Content -LiteralPath $WorkloadContractPath -Raw | ConvertFrom-Json -Depth 64
if ($amendment.amendmentId -ne 'Gate0.G05.LossyAudioOracle.V5.ReferenceRelativeStress.20260827' -or $amendment.status -ne 'owner-approved-controls-required-before-retained-output-reevaluation') { throw 'V5 amendment identity or status is invalid.' }
if ($amendment.extends.contractId -ne $oracle.contractId -or $amendment.extends.sha256 -ne (Hash $OracleContractPath)) { throw 'V5 amendment does not bind the exact V3 contract.' }
$descriptor = @($oracle.referenceDescriptors | Where-Object { $_.id -eq 'stress-4v8a-30s' }); $overlay = @($amendment.descriptorOverlays | Where-Object { $_.referenceDescriptorId -eq 'stress-4v8a-30s' }); $workload = @($workloads.workloads | Where-Object { $_.id -eq 'stress-4v8a' })
if (@($amendment.scope.referenceDescriptorIds).Count -ne 1 -or [string]$amendment.scope.referenceDescriptorIds[0] -ne 'stress-4v8a-30s' -or @($amendment.descriptorOverlays).Count -ne 1 -or $descriptor.Count -ne 1 -or $overlay.Count -ne 1 -or $workload.Count -ne 1) { throw 'V5 stress scope, overlay, descriptor, or workload is not exact and unique.' }
Import-Module (Join-Path $PSScriptRoot 'G05Stage2SmokeHelpers.psm1') -Force; Import-Module (Join-Path $PSScriptRoot 'G05Stage2AV5AudioOracle.psm1') -Force; Import-Module (Join-Path $PSScriptRoot 'G05Stage2ASemanticHelpers.psm1') -Force
Assert-G05Stage2AV5StressOverlay $descriptor[0] $overlay[0]
$truth = Join-Path $OutputDirectory 'stress-4v8a-30s.s16le'; New-G05Stage2AAudioTruth $FixtureRoot $workload[0] $truth $descriptor[0] | Out-Null
if ((Hash $truth) -ne '299846E21A0AF6F1416CCA7BF1BF8ACAC4A5EDDA78EFF9BEB392CC7B992B8CF5') { throw 'Regenerated stress truth does not match the exact V3 descriptor.' }
if (-not ('ReelForge.Gate0.V5AudioControls' -as [type])) { Add-Type -TypeDefinition @'
using System; using System.IO; namespace ReelForge.Gate0 { public static class V5AudioControls { public static short[] Scale(short[] source,double gain){var result=new short[source.Length];for(var i=0;i<source.Length;i++)result[i]=(short)Math.Clamp(Math.Round(source[i]*gain,MidpointRounding.ToEven),short.MinValue,short.MaxValue);return result;} public static short[] DropRight(short[] source,int start,int length){var result=(short[])source.Clone();for(var n=start;n<start+length;n++)result[n*2+1]=0;return result;} public static void Write(string path,short[] samples){var bytes=new byte[samples.Length*2];Buffer.BlockCopy(samples,0,bytes,0,bytes.Length);File.WriteAllBytes(path,bytes);} } }
'@ }
$bytes=[IO.File]::ReadAllBytes($truth); $samples=[int16[]]::new($bytes.Length/2); [Buffer]::BlockCopy($bytes,0,$samples,0,$bytes.Length)
$controls=[ordered]@{'stress-identity'=$samples;'stress-gain-95-percent'=[ReelForge.Gate0.V5AudioControls]::Scale($samples,0.95);'stress-right-low-level-960-sample-dropout'=[ReelForge.Gate0.V5AudioControls]::DropRight($samples,5000,960);'stress-gain-75-percent'=[ReelForge.Gate0.V5AudioControls]::Scale($samples,0.75);'stress-gain-125-percent'=[ReelForge.Gate0.V5AudioControls]::Scale($samples,1.25)}
$expected=@{'stress-identity'=$true;'stress-gain-95-percent'=$true;'stress-right-low-level-960-sample-dropout'=$false;'stress-gain-75-percent'=$false;'stress-gain-125-percent'=$false}; $records=[Collections.Generic.List[object]]::new()
foreach($entry in $controls.GetEnumerator()){ $path=Join-Path $OutputDirectory ($entry.Key+'.s16le'); [ReelForge.Gate0.V5AudioControls]::Write($path,$entry.Value); $result=Test-G05Stage2AV5StressAudio $truth $path $oracle.qualityThresholds $descriptor[0] $overlay[0] 0; if($result.passed-ne$expected[$entry.Key]){throw "V5 control verdict mismatch: $($entry.Key)"};if($entry.Key-eq'stress-right-low-level-960-sample-dropout'-and-not(@($result.failures)-match'reference-relative-window-rms-ratio')){throw'V5 dropout did not fail through the required reference-relative window gate.'};$records.Add([ordered]@{id=$entry.Key;expectedPass=$expected[$entry.Key];actualPass=$result.passed;filename=[IO.Path]::GetFileName($path);size=(Get-Item $path).Length;sha256=(Hash $path);result=$result}) }

$v3Output=Join-Path $OutputDirectory 'legacy-v3-controls'; $v3Json=& pwsh -NoProfile -File (Join-Path $PSScriptRoot 'Invoke-G05LossyAudioOracleControls.ps1') -ReferencePcmPath (Join-Path $FixtureRoot 'F1/f1-sync-440hz-880hz-48000-stereo.pcm') -OutputDirectory $v3Output; if($LASTEXITCODE-ne0){throw'Exact V3 controls failed.'};$v3=$v3Json|ConvertFrom-Json -Depth 64;$vectors=@{};foreach($vector in @($oracle.syntheticControlEvidence.vectors)){if($vectors.ContainsKey([string]$vector.id)){throw'Duplicate frozen V3 control identifier.'};$vectors[[string]$vector.id]=$vector};$v3Actual=@{};foreach($record in @($v3.controls)){if($v3Actual.ContainsKey([string]$record.id)){throw'Duplicate rerun V3 control identifier.'};$v3Actual[[string]$record.id]=$record};if($vectors.Count-ne12-or$v3Actual.Count-ne12-or@($vectors.Keys|Where-Object{$_-notin$v3Actual.Keys}).Count-or@($v3Actual.Keys|Where-Object{$_-notin$vectors.Keys}).Count){throw'Exact V3 control identifier set changed.'};foreach($id in $vectors.Keys){$frozen=$vectors[$id];$record=$v3Actual[$id];if($record.actualPass-ne$frozen.expectedPass-or$record.sha256-ne$frozen.sha256){throw "Exact V3 legacy control changed: $id"}}
$v4Output=Join-Path $OutputDirectory 'v4-controls'; $v4Json=& pwsh -NoProfile -File (Join-Path $PSScriptRoot 'Invoke-G05StructuredAudioOracleControls.ps1') -FixtureRoot $FixtureRoot -OutputDirectory $v4Output -OracleContractPath $OracleContractPath -WorkloadContractPath $WorkloadContractPath; if($LASTEXITCODE-ne0){throw'Exact V4 controls failed.'};$v4=$v4Json|ConvertFrom-Json -Depth 64;$v4SummaryPath=Join-Path $PSScriptRoot 'g0.5-structured-audio-control-result-summary.json';if((Hash $v4SummaryPath)-ne'83097DA638B80D048F84CC86B29BB24463C0B2BF9C2D3ED78CAF658FC73BF5EE'){throw'Canonical V4 control summary hash changed.'};if((Hash $V4AuthoritativeControlReportPath)-ne'2CAEE1C652F292BBF7E9DB6E1DAA0DD7C5E68788C3E5D74F63997DC3775F2AF6'){throw'Authoritative retained V4 control report hash changed.'};$frozenV4=Get-Content $v4SummaryPath -Raw|ConvertFrom-Json -Depth 64;$retention=Get-Content $V4RetentionManifestPath -Raw|ConvertFrom-Json -Depth 128;$v4Group=@($retention.groups|Where-Object groupId -eq 'G05-V4-Structured-Audio-Controls-20260827-001');if($v4Group.Count-ne1){throw'Authoritative retained V4 group is unavailable.'};$retainedReport=@($v4Group[0].files|Where-Object artifactId -eq 'G05-V4-Structured-Audio-Controls-20260827-001/g0.5-structured-audio-oracle-control-results.json');if($retainedReport.Count-ne1-or$retainedReport[0].sha256-ne(Hash $V4AuthoritativeControlReportPath)-or$retainedReport[0].sha256-ne$frozenV4.controlReport.sha256){throw'Authoritative retained V4 report binding is invalid.'};$v4Expected=@{};foreach($file in @($v4Group[0].files|Where-Object{$_.artifactId-match'/typical-(identity|panned-gain-95-percent|right-low-level-960-sample-dropout|gain-75-percent|gain-125-percent)\.s16le$'})){ $id=([IO.Path]::GetFileNameWithoutExtension([string]$file.artifactId));if($v4Expected.ContainsKey($id)){throw'Duplicate authoritative retained V4 control identifier.'};$v4Expected[$id]=$file };$v4Disposition=@{};foreach($record in @($frozenV4.structuredControls)){if($v4Disposition.ContainsKey([string]$record.id)){throw'Duplicate frozen V4 control disposition identifier.'};$v4Disposition[[string]$record.id]=$record};$v4Actual=@{};foreach($record in @($v4.structuredControls)){if($v4Actual.ContainsKey([string]$record.id)){throw'Duplicate rerun V4 control identifier.'};$v4Actual[[string]$record.id]=$record};if($v4Expected.Count-ne5-or$v4Disposition.Count-ne5-or$v4Actual.Count-ne5-or@($v4Expected.Keys|Where-Object{$_-notin$v4Disposition.Keys-or$_-notin$v4Actual.Keys}).Count-or@($v4Disposition.Keys|Where-Object{$_-notin$v4Expected.Keys}).Count-or@($v4Actual.Keys|Where-Object{$_-notin$v4Expected.Keys}).Count){throw'Exact V4 control identifier set changed.'};foreach($id in $v4Expected.Keys){$record=$v4Actual[$id];$prior=$v4Disposition[$id];if($record.actualPass-ne$prior.actualPass-or$record.sha256-ne$v4Expected[$id].sha256){throw "Exact V4 structured control changed: $id"}}
$report=[ordered]@{schemaVersion=1;controlSetId='Gate0.G05.LossyAudioOracle.Controls.V5.ReferenceRelativeStress';status='passed-controls-only-freeze-candidate-pending';amendmentId=$amendment.amendmentId;v3Contract=[ordered]@{path='eng/gate0/g0.5-lossy-audio-oracle-contract.json';sha256=(Hash $OracleContractPath);contractId=$oracle.contractId};routeOutputsEvaluated=$false;routeReencodePerformed=$false;retainedMp4OrWebmOutputsRead=$false;stressTruth=[ordered]@{sha256=(Hash $truth);size=(Get-Item $truth).Length};structuredControls=@($records);legacyV3Controls=[ordered]@{count=$v3Actual.Count;exactBidirectionalIdSetPreserved=$true;allFrozenDispositionsAndHashesPreserved=$true};legacyV4Controls=[ordered]@{authoritativeRetentionGroupId='G05-V4-Structured-Audio-Controls-20260827-001';retentionManifestSha256=(Hash $V4RetentionManifestPath);count=$v4Actual.Count;exactBidirectionalIdSetPreserved=$true;allFrozenDispositionsAndHashesPreserved=$true};executionBoundary=[ordered]@{ffmpegInvoked=$false;ffprobeInvoked=$false;mediaProcessesStarted=$false;retainedCodecOutputsRead=$false}}
$resultPath=Join-Path $OutputDirectory 'g0.5-v5-stress-audio-oracle-control-results.json';$json=$report|ConvertTo-Json -Depth 64;[IO.File]::WriteAllText($resultPath,$json,[Text.UTF8Encoding]::new($false));$candidate=[ordered]@{schemaVersion=1;candidateId='Gate0.G05.LossyAudioOracle.V5.ReferenceRelativeStress.FreezeCandidate.20260827';status='controls-passed-freeze-candidate-not-frozen';amendment=[ordered]@{amendmentId=$amendment.amendmentId;status=$amendment.status;referenceDescriptorIds=@($amendment.scope.referenceDescriptorIds);overlay=[ordered]@{referenceDescriptorId=$overlay[0].referenceDescriptorId;mode=$overlay[0].mode;windowSamples=$overlay[0].windowSamples;minimumOutputToReferenceRmsRatio=$overlay[0].minimumOutputToReferenceRmsRatio;maximumOutputToReferenceRmsRatio=$overlay[0].maximumOutputToReferenceRmsRatio;replacesV3Checks=@($overlay[0].replacesV3Checks)}};authoritativeV4ControlReport=[ordered]@{groupId='G05-V4-Structured-Audio-Controls-20260827-001';artifactId=[string]$retainedReport[0].artifactId;filename=[string]$retainedReport[0].filename;sha256=(Hash $V4AuthoritativeControlReportPath);size=(Get-Item $V4AuthoritativeControlReportPath).Length};controlReport=[ordered]@{path='g0.5-v5-stress-audio-oracle-control-results.json';sha256=(Hash $resultPath);size=(Get-Item $resultPath).Length};frozenInputs=@([ordered]@{path='eng/gate0/g0.5-lossy-audio-oracle-contract.json';sha256=(Hash $OracleContractPath)},[ordered]@{path='eng/gate0/g0.5-lossy-audio-oracle-amendment-v4.json';sha256=(Hash (Join-Path $PSScriptRoot 'g0.5-lossy-audio-oracle-amendment-v4.json'))},[ordered]@{path='eng/gate0/g0.5-lossy-audio-oracle-amendment-v4-freeze.json';sha256=(Hash (Join-Path $PSScriptRoot 'g0.5-lossy-audio-oracle-amendment-v4-freeze.json'))},[ordered]@{path='eng/gate0/g0.5-lossy-audio-oracle-amendment-v5.json';sha256=(Hash $AmendmentPath)},[ordered]@{path='eng/gate0/g0.5-stage2-workload-contract.json';sha256=(Hash $WorkloadContractPath)},[ordered]@{path='eng/gate0/G05Stage2SmokeHelpers.psm1';sha256=(Hash (Join-Path $PSScriptRoot 'G05Stage2SmokeHelpers.psm1'))},[ordered]@{path='eng/gate0/G05Stage2ASemanticHelpers.psm1';sha256=(Hash (Join-Path $PSScriptRoot 'G05Stage2ASemanticHelpers.psm1'))},[ordered]@{path='eng/gate0/G05Stage2AV5AudioOracle.psm1';sha256=(Hash (Join-Path $PSScriptRoot 'G05Stage2AV5AudioOracle.psm1'))},[ordered]@{path='eng/gate0/Invoke-G05LossyAudioOracleControls.ps1';sha256=(Hash (Join-Path $PSScriptRoot 'Invoke-G05LossyAudioOracleControls.ps1'))},[ordered]@{path='eng/gate0/Invoke-G05StructuredAudioOracleControls.ps1';sha256=(Hash (Join-Path $PSScriptRoot 'Invoke-G05StructuredAudioOracleControls.ps1'))},[ordered]@{path='eng/gate0/g0.5-structured-audio-control-result-summary.json';sha256=(Hash $v4SummaryPath)},[ordered]@{path='eng/gate0/Invoke-G05Stage2AV5AudioOracleControls.ps1';sha256=(Hash $PSCommandPath)},[ordered]@{path='eng/gate0/New-G05Stage2AV5AudioOracleFreeze.ps1';sha256=(Hash (Join-Path $PSScriptRoot 'New-G05Stage2AV5AudioOracleFreeze.ps1'))},[ordered]@{path='eng/gate0/artifact-retention-manifest.json';sha256=(Hash $V4RetentionManifestPath)});requiredControlVerdicts=[ordered]@{v5=5;v3=12;v4=5;allPassed=$true};retainedOutputEvaluationAuthorized=$false};$candidatePath=Join-Path $OutputDirectory 'g0.5-v5-stress-audio-oracle-freeze-candidate.json';[IO.File]::WriteAllText($candidatePath,($candidate|ConvertTo-Json -Depth 64),[Text.UTF8Encoding]::new($false));$json
